def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    if maxsize is None:
        return cache()(typed=typed)
    if not isinstance(maxsize, int) or not isinstance(typed, bool):
        raise TypeError("expected int or bool")

    def wrapper(func):
        if not func.__code__.co_flags & CO_VARARGS:
            pass  # function doesn't have *args, so we can cache it
        cache = {}
        hits = misses = 0
        key_types = []
        new_key = {}
        cmt = new_key.__class__ % (len(func.__code__.co_varnames),)
        old_name = func.__name__
        full_doc = func.__doc__
        if full_doc is None:
            full_doc = ""
        func_module = func.__module__
        name = func.__name__
        doc = func.__doc__
        locals = func.__globals__
        if func.__defaults__ is None:
            def_func_args = None
        else:
            def_func_args = "() args, %s" % ', '.join(str(a) for a in func.__defaults__)
        if func.__kwdefaults__ is None:
            def_func_kw = None
        else:
            def_func_kw = "() kwargs, %s" % ', '.join('%s=%r' % (k, v) for k, v in func.__kwdefaults__.items())

        def make_key(args, kwds, typed):
            return (args[0] if args else None, args[1:] if len(args) 
                    > 1 else tuple(), tuple(sorted(kwds.items())))

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            nonlocal cache, key_types, new_key
            if maxsize is not None and len(cache) >= maxsize:
                cache.popitem(last=False)
            key = make_key(args, kwargs, typed)
            sentinel = object
            try:
                result = cache[key]
                hits += 1
            except KeyError:
                result = func(*args, **kwargs)
                misses += 1
            try:
                cache[key] = result
                if len(cache) > maxsize:
                    cache.popitem(last=False)
            except ValueError:
                pass
            return result

        def cache_info():
            return hits, misses, maxsize, len(cache)
        def cache_clear():
            nonlocal cache, hits, misses
            hits = misses = 0
            cache.clear()

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper
    return wrapper

