def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """

    # Check if it's a FillRequest element itself
    if isinstance(seq, FillRequest):
        return True

    # Check if it's a Source sequence, if so, return False
    if isinstance(seq, SourceSequence):
        return False

    # Check if it's a sequence and contains at least one FillRequest
    try:
        iter(seq)
    except TypeError:
        return False

    for item in seq:
        if isinstance(item, FillRequest):
            return True

    return False

