def difference(d1, d2, level=-1):
    if level == 0:
        return d1
    if level >= 1:
        d1 = d1.copy()
    diff = {}
    common_keys = set(d1.keys()) & set(d2.keys())
    for key in d1.keys():
        item = d1[key]
        if key not in d2:
            diff[key] = item
        elif not isinstance(item, dict) or not isinstance(d2[key], dict):
            if item != d2[key]:
                diff[key] = item
        else:
            sub_diff = difference(item, d2[key], level + 1)
            if sub_diff:
                diff[key] = sub_diff
    return diff

def _validate_labels(labels):
    errors = []
    for key, value in labels.items():
        # Validate the key
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
        elif not LABEL_KEY_REGEX.match(key):
            errors.append({key: f"Label key '{key}' does not match the regex {LABEL_KEY_REGEX.pattern}"})

        # Validate the value
        if not isinstance(value, str):
            errors.append({str(value): 'expected string or bytes-like object'})
        elif not LABEL_VALUE_REGEX.match(value):
            errors.append({value: f"Label value '{value}' does not match the regex {LABEL_VALUE_REGEX.pattern}"})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    import krake.data.kubernetes as k8s

    manifest = app.spec.manifest
    if not hasattr(app, 'observer_schema'):
        app.observer_schema = {}

    for resource in manifest:
        resource_name = resource.name if hasattr(resource, 'name') else str(resource)
        if resource_name not in app.observer_schema:
            app.observer_schema[resource_name] = k8s.ObserverSchema.default_for_resource(resource)

    return app.observer_schema

def format(
        self,
        sql: AnyStr,
        params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """
    if not params:
        return sql, params
    if isinstance(params, dict):
        # Named placeholder style
        if self.in_style == 'named':
            return self._format_named(sql, params)
        else:
            # raise TypeError
            raise TypeError('params must be a dict if self.in_style is named')
    elif isinstance(params, (list, tuple)):
        # Positional placeholder style
        if self.in_style == 'positioned' or self.in_style == 'numeric':
            return self._format_positional(sql, params)
        else:
            raise TypeError('params must be a sequence if self.in_style is not named')
    else:
        raise TypeError('Invalid params type: {}'.format(type(params)))

