def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    missing_digests = []
    for file in manifest_files:
        # Assume there's a method to extract digests from a manifest file
        required_digests = self.get_digests_from_manifest(file)
        for digest in required_digests:
            if digest not in digests_used:
                missing_digests.append(digest)
    return missing_digests

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, InventoryValidator):
            raise ValueError("prior must be an InventoryValidator object")

        # Check if the domain elements are the same
        if self._domain_elements != prior._domain_elements:
            raise ValueError("The domain elements of the current and prior inventories must match")

        # Check the physics property specs (PPS)
        for pps in self._physics_property_specs:
            if pps not in prior._physics_property_specs:
                raise ValueError(f"Physics property spec {pps} is not present in the prior inventory")

        # Check the modification properties (MP)
        for mp in self._modification_properties:
            if mp not in prior._modification_properties:
                raise ValueError(f"Modification property {mp} is not present in the prior inventory")

        # Check the properties (P)
        for p in self._properties:
            if p not in prior._properties:
                raise ValueError(f"Property {p} is not present in the prior inventory")

        # Check the prior version of the inventories
        if self._prior_version is not None and prior._prior_version is not None:
            if self._prior_version != prior._prior_version:
                raise ValueError("The prior versions of the inventories must match")

        return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_paths = {}

    for v in sorted(inventory):
        if isinstance(v, bytes):
            v = v.decode('utf-8')

        if version is not None and lexicographic_compare(v, version)[1] >= 1:
            break

        if v in inventory:
            for logical_path in inventory[v]['logical_paths']:
                if logical_path not in logical_paths:
                    logical_paths[logical_path] = set()
                logical_paths[logical_path].add(inventory[v]['files'][logical_path])

    return logical_paths

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary")

        for file_path, checksum_info in fixity.items():
            if file_path not in manifest_files:
                raise ValueError("File %s is not in the manifest" % file_path)
            if not isinstance(checksum_info, dict):
                raise ValueError("Checksum info for file %s must be a dictionary" % file_path)

def files_list(path):
