def _group_files_by_xml_filename(source, xmls, files):
    """
    Group items by their xml file name. Returns a dict of {xml_file_name: package}
    """
    from collections import defaultdict

    packages = defaultdict(list)
    for xml_fname in xmls:
        packages[xml_fname].append(xml_fname)
    for sample in files:
        xml_fname = _get_xml_fname(sample)
        if xml_fname in packages:
            packages[xml_fname].append(sample)
    return {xml_fname: Package(source, xml_fname, files) for xml_fname, files in packages.items()}

