def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for arg in args:
        if arg.func is And:
            for i, a in enumerate(arg.args):
                for b in arg.args[:i] + arg.args[i+1:]:
                    if a.equals(b):
                        result.append(a)
                        break
                    if a.equals(~b):
                        result.append(And(a, b))
                        break
        elif arg.func is Or:
            for i, a in enumerate(arg.args):
                for b in arg.args[:i] + arg.args[i+1:]:
                    if a.equals(b):
                        result.append(a)
                        break
                    if a.equals(~b):
                        result.append(Or(a, b))
                        break
    return result

def _fromutc(self, dt):
        """
        Given a timezone-aware datetime in a given timezone, calculates a
        timezone-aware datetime in a new timezone.

        Since this is the one time that we *know* we have an unambiguous
        datetime object, we take this opportunity to determine whether the
        datetime is ambiguous and in a "fold" state (e.g. if it's the first
        occurrence, chronologically, of the ambiguous datetime).

        :param dt:
            A timezone-aware :class:`datetime.datetime` object.
        """
        if not dt.tzinfo:
            dt = dt.replace(tzinfo=self)

        dt_dst = dt.dst()
        if not dt_dst:
            return dt - self.utcoffset(dt)

        # Results in a list of possible datetimes in UTC
        deltas = [dt - self.utcoffset(dt), dt - self.utcoffset(dt) + dt_dst]

        for _dt in deltas:
            if _dt.tzinfo is None:
                _dt = _dt.replace(tzinfo=pytz.utc)
            else:
                _dt = _dt.astimezone(pytz.utc)

        try:
            delta_from_default = deltas[0] - deltas[self._utc_inverse_localize(dt.utctimetuple())]
        except IndexError:
            delta_from_default = timedelta(0)

        # It's unambiguous, or it's ambiguous and the user wants the default
        if delta_from_default == timedelta(0):
            return deltas[0].replace(tzinfo=pytz.utc)

        # It's ambiguous, and the user wants the other one
        return deltas[1].replace(tzinfo=pytz.utc)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func

