def render(pieces, style):
    """Render the given version pieces into the requested style."""

    if pieces["closest-tag"]:
        rendered = pieces["closest-tag"]
        if pieces["distance"]:
            rendered += "-%d-g%s" % (pieces["distance"], pieces["short"])
    else:
        rendered = "unknown"

    if style:
        if style == "pep440":
            # convert git-style version to pep440
            if pieces["distance"]:
                rendered = rendered.replace("-", ".dev")
            if pieces.get("dirty") and rendered.endswith("."):
                rendered = rendered + "dirty"
        elif style == "tag":
            pass
        elif style == "deprecated-pep440":
            if pieces["distance"]:
                rendered = "%s.post%d" % (pieces["closest-tag"],
                                          pieces["distance"])
            if pieces.get("dirty"):
                rendered += ".dev0"
        elif style == "simple":
