def deep_merge_nodes(nodes):
    result = []
    for key, value in nodes:
        merged = False
        for i, (existing_key, existing_value) in enumerate(result):
            if existing_key.value == key.value:
                if isinstance(existing_value, MappingNode) and isinstance(value, MappingNode):
                    merged_value = deep_merge_nodes([
                        kv for kv in existing_value.value
                    ] + [kv for kv in value.value])
                    result[i] = (existing_key, MappingNode(
                        tag=existing_value.tag,
                        value=merged_value
                    ))
                else:
                    result[i] = (key, value)
                merged = True
                break
        if not merged:
            result.append((key, value))
    return result

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    if len(unparsed_arguments) == 0:
        argv = sys.argv[1:]
    else:
        argv = list(unparsed_arguments)
    parser = build_arg_parser()
    if len(parser._subparsers._group_actions) == 0:
        result = parser.parse_args(argv)
    else:
        subparser_names = list(parser._subparsers._name_parser_map.keys())
        if len(argv) == 0 or argv[0] not in subparser_names:
            # There are no sub-arguments, so parse the global arguments.
            global_args_parser = parser._get_global_args_parser()
            result = global_args_parser.parse_args(argv)
            result = {'global': result}
        else:
            # There are sub-arguments, so parse the global and sub-arguments.
            subparser_name = argv[0]
            global_args_parser = parser._get_global_args_parser()
            subparser_args_parser = parser._subparsers._name_parser_map[subparser_name]
            subparser_args = subparser_args_parser.parse_args(argv[1:])
            global_args, unparsed_global_args = global_args_parser.parse_known_args(argv[1:])
            result = {'global': global_args}
            result[subparser_name] = subparser_args
    return result

