def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        for sc in c.__subclasses__():
            if sc not in seen:
                queue.add(sc)

    seen.remove(cls)
    return seen

def unquote(name):
    """Remove quote from the given name."""
    matches = re.match(r"^(?P<quote>[\'\"])(.*?)(?P=quote)$", name)
    if matches:
        return matches.group(2)
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    if platform == 'this':
        import sys
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        # POSIX: split on whitespace, respect quotes
        pattern = r"(\S+|\"[^\"]+\"|'[^']*')"
        tokens = re.findall(pattern, s)
        # Remove quotes
        result = []
        for token in tokens:
            if token.startswith('"') and token.endswith('"'):
                token = token[1:-1]
            elif token.startswith("'") and token.endswith("'"):
                token = token[1:-1]
            result.append(token)
        return result
    elif platform == 0:  # Windows
        # Windows CMD: split on whitespace, no special quote handling (simplified)
        return s.split()
    else:
        raise ValueError(f"Invalid platform value: {platform}")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency == "always":
        return None

    try:
        number, unit = frequency.split()
    except ValueError:
        raise ValueError("Frequency string must be in the form '<number> <unit>'")

    if unit in ["seconds", "second", "s"]:
        return datetime.timedelta(seconds=int(number))
    elif unit in ["minutes", "minute", "m"]:
        return datetime.timedelta(minutes=int(number))
    elif unit in ["hours", "hour", "h"]:
        return datetime.timedelta(hours=int(number))
    elif unit in ["days", "day", "d"]:
        return datetime.timedelta(days=int(number))
    elif unit in ["weeks", "week", "w"]:
        return datetime.timedelta(weeks=int(number))
    else:
        raise ValueError("Unsupported time unit: {}".format(unit))

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    import os

    import tempfile
    if os.path.exists(config_filename) and not overwrite:
        raise ValueError("Configuration file already exists: {}".format(config_filename))
    directory = os.path.dirname(config_filename)
    if directory and not os.path.exists(directory):
        os.makedirs(directory)
    # Write to a temporary file in the same directory to ensure atomicity
    fd, temp_path = tempfile.mkstemp(dir=directory, prefix=".config_", suffix=".tmp")
    try:
        try:
            os.fchmod(fd, mode)
            with os.fdopen(fd, 'w') as f:
                f.write(rendered_config)
        except:
            fd = None
            raise
        finally:
            if fd is not None:
                os.close(fd)
        os.replace(temp_path, config_filename)
    except:
        try:
            os.unlink(temp_path)
        except OSError:
            pass
        raise

