def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__

    :param bases: A tuple of base classes.
    :param explicit_mc: An explicit metaclass, if specified.
    :returns: The determined metaclass.
    :rtype: type
    """
    if explicit_mc:
        return explicit_mc
    if not bases:
        return type
    metaclass = type
    for base in bases:
        if isinstance(base, type):
            base_metaclass = type(base)
            if issubclass(metaclass, base_metaclass):
                metaclass = base_metaclass
    return metaclass

def pop(self, key, default=__marker):
        """
        D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
        If key is not found, d is returned if given, otherwise KeyError is raised.
        """
        if key not in self:
            if default is not __marker:
                return default
            raise KeyError(key)
