    def _get_link_rel(links, rel):
        """
        Helper to get the href of a link with a specific rel type.
        """
        for link in links:
            if link.get("rel") == rel:
                return link.get("href")
        return None

    def xrd_to_dict(xrd_string):
        """
        Simplified XRD parser to convert XRD XML to a dictionary structure.
        This is a helper function for parsing XRD format webfinger.
        """
        root = ET.fromstring(xrd_string.encode('utf-8'))

        def _elem_to_elem_dict(elem):
            result = {}
            if elem.text:
                result['text'] = elem.text.strip()
            if elem.attrib:
                result['attrib'] = dict(elem.attrib)
            children = []
            for child in elem:
                child_dict = _elem_to_elem_dict(child)
                child_dict['tag'] = child.tag
                children.append(child_dict)
            if children:
                result['children'] = children
            return result

        def _find_all_by_tag(parent, tag_name):
            result = []
            for child in parent.get('children', []):
                if child.get('tag') == tag_name:
                    result.append(child)
                result.extend(_find_all_by_tag(child, tag_name))
            return result

        root_dict = _elem_to_elem_dict(root)
        services = []
        for child in root_dict.get('children', []):
            if child.get('tag') == 'Service':
                services.append(child)

        # Extract subject from XRDS
        subject = None
        for child in root_dict.get('children', []):
            if child.get('tag') == 'Subject':
                subject = child.get('text')

        parsed = {'Subject': subject, 'Service': []}
        for serv in services:
            service_data = {}
            # Extract URI from Service
            for sub_child in serv.get('children', []):
                if sub_child.get('tag') == 'URI':
                    # Check the parent element to determine the type
                    # Look for the parent container type
                    parent_type = None
                    # We need to walk back or keep track
                    # For simplicity, use the standard structure
                    # The type is in the parent element's tag or attribute
                    # Typically: <Service><Type>...</Type><URI>...</URI></Service>
                    # So we need to find the Type sibling
                    type_val = None
                    for cc in serv.get('children', []):
                        if cc.get('tag') == 'Type' and cc.get('text'):
                            type_val = cc.get('text').strip()
                            break
                    ur_dict = {
                        'URI': sub_child.get('text').strip(),
                        'Type': type_val
                    }
                    service_data.setdefault('Type', [])
                    service_data['Type'].append(type_val)
                    service_data['URI'].append(sub_child.get('text').strip())

            # Convert the list-style to dict-style
            service_obj = {}
            if 'URI' in service_data and 'Type' in service_data:
                # Pair them by index
                n = len(service_data['URI'])
                for i in range(n):
                    t = service_data['Type'][i] if i < len(service_data['Type']) else None
                    u = service_data['URI'][i]
                    service_obj[t] = u
            parsed['Service'].append(service_obj if service_obj else {'URI': None, 'Type': None})

        return parsed
    try:
        # Try JSON first
        json_doc = json.loads(document)
        return {
            "subject": json_doc.get("subject"),
            "hcard_url": _get_link_rel(json_doc.get("links", []), "http://tools.ietf.org/html/carddav#hcard"),
            "inbox_url": _get_link_rel(json_doc.get("links", []), "http://tools.ietf.org/html/carddav#inbox"),
            "person_address": json_doc.get("subject", "").replace("acct:", ""),
            "host": json_doc.get("subject", "").split("@")[-1],
        }
    except (ValueError, AttributeError):
        pass

    # Try XRD format
    try:
        xrd = xrd_to_dict(document)
        service = xrd.get("Service", [])
        if isinstance(service, dict):
            service = [service]

        subject = None
        hcard_url = None
        inbox_url = None

        for serv in service:
            if serv.get("Type") == "http://portablecontact.net/spec/uri":
                subject = serv.get("URI", serv.get("Subject"))
            elif serv.get("Type") == "http://tools.ietf.org/html/carddav#hcard":
                hcard_url = serv.get("URI")
            elif serv.get("Type") == "http://tools.ietf.org/html/carddav#inbox":
                inbox_url = serv.get("URI")

        if subject is None:
            raise ValueError("No subject found in XRD document")

        return {
            "subject": subject,
            "hcard_url": hcard_url,
            "inbox_url": inbox_url,
            "person_address": subject.replace("acct:", ""),
            "host": subject.split("@")[-1],
        }
    except Exception:
        raise ValueError("Failed to parse webfinger document")

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    from urllib.parse import quote, quote_from_bytes

    from typing import Optional
    try:
        host = handle.split("@")[1]
    except (IndexError, AttributeError):
        logger.warning("try_retrieve_webfinger_document: invalid handle: %s", handle)
        return None

    if not host:
        return None

    # Try well-known webfinger path first
    url = f"https://{host}/.well-known/webfinger?resource=acct:{quote(handle)}"
    try:
        response = fetch_document(url)
        document, status_code, exception = response
        if exception:
            logger.warning("Error fetching webfinger document from %s: %s", url, exception)
            return None
        if status_code == 200 and document:
            return document.decode('utf-8', errors='replace')
        else:
            logger.warning("Non-200 status code %s or empty response from %s", status_code, url)
            return None
    except Exception as e:
        logger.exception("Unexpected error when trying to retrieve webfinger document from %s: %s", url, e)
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    logger.debug("send_document: url=%s, data=%s, timeout=%s, method=%s", url, data, timeout, method)
    headers = CaseInsensitiveDict({
        'User-Agent': USER_AGENT,
    })
    if "headers" in kwargs:
        # Update from kwargs
        headers.update(kwargs.get("headers"))
    kwargs.update({
        "data": data, "timeout": timeout, "headers": headers
    })

    # Choose the appropriate method based on the 'method' argument
    method = method.lower()
    if method == 'post':
        request_func = requests.post
    elif method == 'get':
        request_func = requests.get
    elif method == 'put':
        request_func = requests.put
    elif method == 'delete':
        request_func = requests.delete
    elif method == 'patch':
        request_func = requests.patch
    else:
        # Default to post if unknown method, or raise an error? 
        # The docstring says "defaults to post", so maybe we treat invalid as post?
        # Or better, just use requests.request? But the example uses requests.post.
        # Let's stick to using requests.request for flexibility if method is not standard.
        pass

    # A more robust approach: use requests.request for arbitrary methods
    try:
        response = requests.request(method, url, *args, **kwargs)
        logger.debug("send_document: response status code %s", response.status_code)
        return response.status_code, None
    except RequestException as ex:
        logger.debug("send_document: exception %s", ex)
        return None, ex

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    file_names = []
    for settings_dir in settings_dirs:
        for file_name in sorted(os.listdir(settings_dir)):
            if file_name.endswith(spec_option):
                file_names.append(os.path.join(settings_dir, file_name))
    return file_names

