def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""

    deprecated_args = {}
    for option in self.options:
        if option.deprecated_in_favour_of:
            deprecated_args[option.name] = option.deprecated_in_favour_of
    return deprecated_args

def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        for arg_name in os.environ.get('CEQAP_DEPRECATED_ARGS', '').split(','):
            if arg_name in cli_args or arg_name in answer_file_args:
                self.log.warning('The argument %s is deprecated.' % arg_name)

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    option_specs = []
    for option in self.parser._optionals._option_strings.values():
        if option.dest == command_name:
            option_specs.append(option)
    return option_specs

def get_option_spec(self, command_name, argument_name):
        """Gets the specification for the specified option name. """
        command = self.commands.get(command_name)
        if command is None:
            return None
        return command.options.get(argument_name)

def validate_requires_args(self, args):
        """Check if all the required arguments have been provided. """
        for arg_name in self.requires_args:
            if arg_name not in args:
                raise ValueError(f"Required argument {arg_name} is missing.")

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        for arg in args:
            if hasattr(arg, 'length') and hasattr(arg, 'value'):
                if len(str(arg.value)) > arg.length:
                    raise ValueError("The length of the value for {} exceeds the specified length".format(arg.name))

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        for arg_name, arg in args.items():
            if hasattr(arg, 'choices') and arg.choices:
                if arg.value not in arg.choices:
                    raise ValueError(
                        "Invalid value '{}' for argument '{}'. Must be one of: {}".format(
                            arg.value, arg_name, ', '.join(map(str, arg.choices))))

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        for arg in args:
            min_val = arg.min_val
            max_val = arg.max_val
            value = arg.value
            if min_val is not None and value < min_val:
                raise ValueError(f"{arg.name}: value {value} is less than minimum value {min_val}")
            if max_val is not None and value > max_val:
                raise ValueError(f"{arg.name}: value {value} is greater than maximum value {max_val}")

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        extra_vars = []

    if not isinstance(vars_dict, dict):
        vars_dict = {}

    for extra_var in extra_vars:
        if isinstance(extra_var, dict):
            for key, value in extra_var.items():
                vars_dict[key] = value
        elif isinstance(extra_var, str) and '=' in extra_var:
            key, value = extra_var.split('=', 1)
            vars_dict[key.strip()] = value.strip()

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    cmd = ["ansible-playbook"]
    if verbose is not None:
        cmd.append("-{}".format("v" * verbose))
    if extra_vars:
        for key, value in extra_vars.items():
            cmd.append("--extra-vars")
            cmd.append("{}={}".format(key, value))
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, list):
                for v in value:
                    cmd.append(key)
                    cmd.append(str(v))
            else:
                cmd.append(key)
                cmd.append(str(value))
    cmd.append(playbook_path)
    return ir_workspace.execute(cmd)

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not values_dict:
        return values_dict

    if parser_name not in self.parser_names:
        raise KeyError(f"Parser name '{parser_name}' is not registered.")

    parser = self.parsers[parser_name]

    for key, value in values_dict.items():
        if value is None:
            continue

        # Find the argument action for this key
        action = None
        for action_obj in parser._actions:
            if key in action_obj.option_strings:
                action = action_obj
                break

        if action is not None and action.type is not None:
            try:
                values_dict[key] = action.type(value)
            except Exception:
                # If conversion fails, leave the value as is or handle error as needed
                pass
        elif action is not None and action.nargs == 0:
            # Action with nargs=0 usually means flag, but covered above
            pass

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    spec_path = os.path.join(plugin_dir, 'plugin_spec.yaml')
    if not os.path.exists(spec_path):
        return {}

    with open(spec_path, 'r') as f:
        spec = yaml.safe_load(f)

    flat_dict = {}

    def flatten(d, prefix=''):
        for k, v in d.items():
            key = f"{prefix}.{k}" if prefix else k
            if isinstance(v, dict):
                flatten(v, key)
            elif isinstance(v, list):
                flat_dict[key] = v
            else:
                flat_dict[key] = v

    flatten(spec)
    return flat_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        os.environ['CONFIG_PATH'] = str(self.config_path)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError("Path %s does not start with root %s" % (path, root))
    return path[len(root):]
